     "headline": "US voters decided 41 local data-centre ballot measures, approving bans and limits in nearly every contest",
     "sources": [
      {
       "name": "Ballotpedia",
       "url": "https://news.ballotpedia.org/2026/11/03/voters-in-ten-states-will-vote-on-data-center-related-ballot-measures-november-3/"
      },
      {
       "name": "Fortune",
       "url": "https://fortune.com/2026/11/04/ohio-data-center-ballot-measures-midterm-elections/"
      },
      {
       "name": "Stateline",
       "url": "https://stateline.org/2026/11/04/voters-across-the-country-reject-data-centers/"
